/* No.014 */
(() => {
const TEX = {"front": "front.jpg", "back": "back.jpg", "sheen": "sheen.png"};
const FACE_H = {"b16": 1, "n": 240, "x0": -1, "x1": 1, "y0": 1, "y1": -1, "h": ""};
/* No.014 antique-gold openwork: a twisted rope rim, gold beads, and pearly paisley enamel whose soft sheen moves with the angle.
   the photo carries the colours; a soft sheen is added only on the enamel */
function buildN() {
  const grp = new THREE.Group();
  const pm = pearlMat(tex(TEX.front), loader.load(TEX.sheen));
  pm.color = new THREE.Color(0xd2c8bc);
  pm.metalness = .15; pm.roughness = .3;
  pm.clearcoat = .5; pm.clearcoatRoughness = .1; pm.envMapIntensity = .55;
  pm.emissiveMap = pm.map; pm.emissive = new THREE.Color(0xffffff); pm.emissiveIntensity = .5;
  const basePm = pm.onBeforeCompile;
  pm.onBeforeCompile = (sh) => {
    basePm(sh);
    sh.fragmentShader = sh.fragmentShader
      .replace('mix(vec3(1.0, 0.80, 0.74), vec3(0.86, 0.88, 1.0)', 'mix(vec3(1.0, 0.86, 0.8), vec3(0.95, 0.9, 0.92)')
      .replace('tint * sh * fb.b * 0.85', 'tint * sh * fb.b * 0.12');
  };
  const front = new THREE.Mesh(cloverRelief(FACE_H, .0, .14), pm);
  front.onBeforeRender = (r, s, cam) => { pm.userData.uMV.value.setFromMatrix4(new THREE.Matrix4().multiplyMatrices(cam.matrixWorldInverse, front.matrixWorld)); };
  grp.add(front);
  grp.add(new THREE.Mesh(rim(1, .03, -.08, 200), new THREE.MeshStandardMaterial({ color: 0x8a6a2a, metalness: 1, roughness: .35, envMapIntensity: 1.2 })));
  // back: antique-gold plate with a sunburst texture, slightly domed, and a loop shank
  const backZ = (x, y) => { const r = Math.min(1, Math.hypot(x, y)); return -.08 - .06 * (1 - r * r); };
  const backMat = new THREE.MeshStandardMaterial({ map: tex(TEX.back), metalness: .9, roughness: .38, envMapIntensity: 1.2, side: THREE.DoubleSide });
  grp.add(new THREE.Mesh(cap(1, 48, 200, backZ, -1, false), backMat));
  const s = new THREE.Shape();
  s.moveTo(-.12, 0); s.lineTo(-.12, .15); s.quadraticCurveTo(-.12, .22, -.05, .22); s.lineTo(.05, .22); s.quadraticCurveTo(.12, .22, .12, .15); s.lineTo(.12, 0); s.closePath();
  const hole = new THREE.Path(); hole.absarc(0, .12, .045, 0, Math.PI * 2, true); s.holes.push(hole);
  const sg = new THREE.ExtrudeGeometry(s, { depth: .1, bevelEnabled: true, bevelThickness: .012, bevelSize: .012, bevelSegments: 3, curveSegments: 16 });
  sg.rotateX(-Math.PI / 2); sg.rotateZ(Math.PI / 2); sg.translate(.05, .02, -.13);
  grp.add(new THREE.Mesh(sg, new THREE.MeshStandardMaterial({ color: 0xc9a44e, metalness: 1, roughness: .3, envMapIntensity: 1.2 })));
  return grp;
}
buildN.env = 'jewel';
viewer(document.getElementById('cv'), buildN, 'v');
})();
